# Builds the committed track-chain catalogue from native-validated effect presets.
# Run node tools/export-presets.mjs first, then python tools/make-track-chains.py.
import copy, json, re
from pathlib import Path
root = Path(__file__).resolve().parents[1]
banks = json.loads((root / 'effect-presets.test.json').read_text())
alias = dict(eq='s4000eq', comp='s4000comp', deess='s4000deesser', level='s4000leveler', tube='s4000tubecomp', enhance='s4000vocalenhancer', dynamics='s4000vocaldynamics', gate='s4000gate', sat='s4000saturator', delay='s4000delay', double='s4000doubler', width='s4000width', transient='s4000transient', tremolo='s4000tremolo', crush='s4000crusher', chorus='chorus', room='reverb', tune='s4000tune', limit='s4000hardlimit', masterlimit='s4000limiter')
labels = dict(eq='Parametric EQ', comp='Compressor', deess='De-esser', level='Vocal Leveler', tube='Tube-style Compressor', enhance='Vocal Enhancer', dynamics='Vocal Dynamics', gate='Noise Gate', sat='Saturator', delay='Delay', double='Vocal Doubler', width='Stereo Width', transient='Transient Shaper', tremolo='Tremolo / Auto Pan', crush='Bit Crusher', chorus='Chorus', room='Reverb', tune='Pitch Correction', limit='Hard Limiter', masterlimit='Limiter')
def s(kind, name, **values):
    preset = next(p for p in banks[alias[kind]] if p['name'] == name)
    actual = copy.deepcopy(preset['values']); actual.update(values)
    if kind == 'comp': actual['autoMakeup'] = 0
    return dict(type=alias[kind], name=labels[kind], setting=name, values=actual)
def safe(): return s('limit', 'Vocal sample safety -2 dBFS')
def eq(name='Vocal clarity', **v): return s('eq', name, **v)
def c(name='Vocal', **v): return s('comp', name, **v)
def d(name='Gentle vocal', **v): return s('deess', name, **v)
def r(name='Lead vocal - small dark room', **v): return s('room', name, **v)
def e(name='Lead vocal clarity', **v): return s('enhance', name, **v)
def sat(name='Tape vocal', **v): return s('sat', name, **v)
chains=[]
def add(category, name, description, *plugins):
    slug=lambda x: re.sub('[^a-z0-9]+','-',x.lower()).strip('-')
    chains.append(dict(id=slug(category)+'--'+slug(name),category=category,name=name,description=description,plugins=list(plugins)))
